input.command:
# Parse .env.test into JSON and POST to CI secret sync endpoint
node -e "
const fs = require('fs');
const https = require('http');

// Read and parse .env.test
const envContent = fs.readFileSync('.env.test', 'utf8');
const lines = envContent.split('\n').filter(line => line && !line.startsWith('#'));
const envVars = {};

lines.forEach(line => {
  const [key, value] = line.split('=');
  if (key && value) {
    envVars[key.trim()] = value.trim();
  }
});

// POST to CI secret sync endpoint
const postData = JSON.stringify(envVars);

const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/ci-secret-sync',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

const req = https.request(options, (res) => {
  console.log(\`Status: \${res.statusCode}\`);
});

req.on('error', (e) => {
  console.error(\`Problem with request: \${e.message}\`);
});

req.write(postData);
req.end();
"

