const express = require('express');
const { Pool } = require('pg');
const app = express();

// Parse DATABASE_URL from environment variables
const databaseUrl = process.env.DATABASE_URL;

// Create a PostgreSQL connection pool if DATABASE_URL is provided
let pool;
if (databaseUrl) {
  pool = new Pool({
    connectionString: databaseUrl,
  });
}

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Healthz endpoint for Kubernetes readiness probe
app.get('/healthz', async (req, res) => {
  try {
    // If no database configured, return ok
    if (!pool) {
      return res.status(200).json({ db: 'ok' });
    }

    // Test database connectivity
    const client = await pool.connect();
    try {
      await client.query('SELECT 1');
      res.status(200).json({ db: 'ok' });
    } finally {
      client.release();
    }
  } catch (error) {
    console.error('Database health check failed:', error);
    res.status(503).json({ db: 'fail', error: error.message });
  }
});

