const fs = require('fs');
const https = require('https');

// Read .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse environment variables into JSON object
const envVars = {};
const lines = envContent.split('\n').filter(line => line.trim() && !line.startsWith('#'));
lines.forEach(line => {
  const [key, value] = line.split('=');
  if (key && value) {
    envVars[key.trim()] = value.trim();
  }
});

// Send to CI secret sync endpoint
const postData = JSON.stringify(envVars);

const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/ci-secret-sync',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

const req = https.request(options, (res) => {
  console.log(`Status: ${res.statusCode}`);
  res.on('data', (chunk) => {
    process.stdout.write(chunk);
  });
  res.on('end', () => {
    console.log('CI secret sync completed');
  });
});

req.on('error', (e) => {
  console.error(`Problem with request: ${e.message}`);
});

req.write(postData);
req.end();

